export const publicationRecords:PublicationRecord[]=rawPublications.map(item=>({
  ...item,
  id:asPublicationId(item.id),
  institutionIds:item.institutionIds.map(asInstitutionId),
  identifiers:item.doi?[{scheme:'doi' as const,value:item.doi,uri:item.url,preferred:true,verification:'verified' as const,origin:'publisher' as const}]:[],
  contributors:[{name:item.authors[0],role:'author' as const,institutionIds:item.institutionIds.map(asInstitutionId),displayOnly:true}],
}))
export const publicationsById=Object.fromEntries(publicationRecords.map(item=>[String(item.id),item])) as Record<string,PublicationRecord>
